      });
    }

    const copyScheduleBtn = $("#copy-schedule-btn");
    const copyScheduleRegion = $("#copy-schedule-region");
    if (copyScheduleBtn && copyScheduleRegion) {
      copyScheduleBtn.addEventListener("click", function () {
